 async function uploadPlayerPhoto(e){const file=e.target.files?.[0];if(!file||!selectedPlayer)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){N('Bitte JPG, PNG oder WEBP bis maximal 5 MB auswählen.');e.target.value='';return}PB(true);PP(0);PST('Upload wird vorbereitet…');let uploadedPath=null,dbSaved=false;try{const{data:{session:authSession}}=await sb.auth.getSession();if(!authSession?.access_token)throw new Error('Sitzung abgelaufen. Bitte erneut anmelden.');const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';const oldPath=selectedPlayer.photo_path||null;const path=session.user.id+'/'+selectedPlayer.player_id+'-'+Date.now()+'.'+ext;uploadedPath=path;PST('Foto wird hochgeladen…');await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();const objectPath=path.split('/').map(encodeURIComponent).join('/');xhr.open('POST',url+'/storage/v1/object/player-photos/'+objectPath);xhr.setRequestHeader('Authorization','Bearer '+authSession.access_token);xhr.setRequestHeader('apikey',key);xhr.setRequestHeader('Content-Type',file.type);xhr.setRequestHeader('x-upsert','false');xhr.upload.onprogress=ev=>{if(ev.lengthComputable)PP(Math.min(99,Math.round(ev.loaded/ev.total*100)))};xhr.onload=()=>{if(xhr.status>=200&&xhr.status<300){PP(100);resolve()}else{let message='Upload fehlgeschlagen (HTTP '+xhr.status+')';try{message=JSON.parse(xhr.responseText).message||JSON.parse(xhr.responseText).error||message}catch{}reject(new Error(message))}};xhr.onerror=()=>reject(new Error('Netzwerkfehler beim Foto-Upload.'));xhr.onabort=()=>reject(new Error('Foto-Upload abgebrochen.'));xhr.send(file)});PST('Foto wird dem Spieler zugeordnet…');const{data:updatedRow,error:dbErr}=await sb.from('players').update({photo_path:path}).eq('player_id',selectedPlayer.player_id).select('photo_path').maybeSingle();if(dbErr||!updatedRow?.photo_path)throw dbErr||new Error('Foto konnte nicht dem Spieler zugeordnet werden.');dbSaved=true;const updated={...selectedPlayer,photo_path:path};SP(updated);D(prev=>prev.map(p=>p.player_id===updated.player_id?{...p,photo_path:path}:p));PST('Foto gespeichert.');if(oldPath&&oldPath!==path){PST('Altes Foto wird gelöscht…');const{error:deleteErr}=await sb.storage.from('player-photos').remove([oldPath]);if(deleteErr)throw new Error('Neues Foto ist gespeichert, aber das alte Foto konnte nicht gelöscht werden: '+deleteErr.message)}PP(100);N(oldPath?'Neues Foto gespeichert. Das alte Foto wurde gelöscht.':'Spielerfoto gespeichert.')}catch(err){if(uploadedPath&&!dbSaved){await sb.storage.from('player-photos').remove([uploadedPath])}N(err.message||'Foto konnte nicht hochgeladen werden.')}finally{PB(false);setTimeout(()=>{PP(0);PST('')},700);if(e.target)e.target.value=''}}
 async function load(){if(!sb||!session)return;L(true);try{const{data:pr,error}=await sb.from('profiles').select('*').eq('id',session.user.id).single();if(error)throw error;P(pr);if(pr.role==='scout'&&pr.approval_status!=='approved'){D([]);return}const{data,error:pe}=await sb.from('players').select('*').order('player_id');if(pe)throw pe;D((data||[]).map(p=>({...p,id:p.player_id,positions:p.positions||[],ratings:p.ratings||{}})));if(pr.role==='admin'){const{data:s,error:se}=await sb.from('profiles').select('*').eq('role','scout').order('scout_number',{ascending:true});if(se)throw se;SC(s||[]);}}catch(e){N(e.message)}finally{L(false)}}
 useEffect(()=>{if(!sb)return;sb.auth.getSession().then(({data})=>{if(data.session){S({user:data.session.user});sb.rpc('scout_heartbeat')}});const{data:{subscription}}=sb.auth.onAuthStateChange((event,s)=>{if(event==='PASSWORD_RECOVERY'){AM('update-password');S(null);return}if(s){S({user:s.user});if(event==='SIGNED_IN'){sb.rpc('scout_mark_login');setLoginIntroUsername(s.user.user_metadata?.username||s.user.email?.split('@')[0]||'Benutzer');setLoginIntroActive(true)}}else{S(null);P(null);D([]);setLoginIntroActive(false)}});return()=>subscription.unsubscribe()},[]);
