 async function deleteDeletionLogs(ids){if(!admin||!ids.length)return;const label=ids.length===deletionLogs.length?'alle Protokolle':ids.length+' ausgewählte Protokolle';if(!window.confirm('Möchtest du wirklich '+label+' endgültig löschen? Die bereits gelöschten Spieler bleiben unverändert.'))return;L(true);try{const{error}=await sb.from('player_deletion_logs').delete().in('id',ids);if(error)throw error;DL(prev=>prev.filter(log=>!ids.includes(log.id)));SDL(prev=>prev.filter(id=>!ids.includes(id)));N(ids.length+' Protokoll(e) gelöscht. Spielerdaten und Spieler-ID-Fortlauf bleiben unverändert.')}catch(e){N('Protokolle konnten nicht gelöscht werden: '+e.message)}finally{L(false)}}
