 async function copyTemporaryPassword(){const value=String(passwordDialog?.password||'');if(!value)return;let copied=false;try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);copied=true}}catch{}if(!copied){let field=null;try{field=document.createElement('textarea');field.value=value;field.setAttribute('readonly','');field.style.position='fixed';field.style.top='0';field.style.left='-9999px';field.style.opacity='0';document.body.appendChild(field);field.focus();field.select();field.setSelectionRange(0,field.value.length);copied=document.execCommand('copy')}catch{copied=false}finally{if(field)field.remove()}}SPCS(copied?'Passwort wurde kopiert.':'Kopieren nicht möglich. Bitte das Passwort gedrückt halten und manuell kopieren.')}
 async function createScout(e){e.preventDefault();if(!admin)return;if(newScout.password.length<12){N('Das Startpasswort muss mindestens 12 Zeichen lang sein.');return}if(newScout.password!==newScout.password2){N('Die Startpasswörter stimmen nicht überein.');return}L(true);try{const{data:{session:authSession}}=await sb.auth.getSession();if(!authSession?.access_token)throw new Error('Sitzung abgelaufen. Bitte erneut anmelden.');const response=await fetch('/api/scouts',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+authSession.access_token},body:JSON.stringify(newScout)});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'Scout konnte nicht angelegt werden.');NS({username:'',email:'',password:'',password2:''});N('Scout '+result.username+' wurde angelegt und wartet auf deine Freischaltung.');await load();}catch(e){N(e.message||'Scout konnte nicht angelegt werden.')}finally{L(false)}}
 async function resetScoutPassword(s){if(!admin||!s?.id)return;const label=s.username||s.email||'diesen Scout';if(!window.confirm('Temporäres Passwort für Scout „'+label+'“ erzeugen?\\n\\nDas bisherige Passwort wird sofort ungültig. Das neue Passwort wird nur einmal angezeigt.'))return;L(true);try{const{data:{session:authSession}}=await sb.auth.getSession();if(!authSession?.access_token)throw new Error('Sitzung abgelaufen. Bitte erneut anmelden.');const response=await fetch('/api/scouts/'+encodeURIComponent(s.id)+'/reset-password',{method:'POST',headers:{Authorization:'Bearer '+authSession.access_token}});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'Passwort konnte nicht zurückgesetzt werden.');SPD({label,password:result.temporary_password});SPCS('');N('Temporäres Passwort für '+label+' wurde erzeugt.');}catch(e){N(e.message||'Passwort konnte nicht zurückgesetzt werden.')}finally{L(false)}}
