 const wingPlayers=useMemo(()=>players.filter(p=>p.foot===(wingSide==='RF'?'Rechtsfuß':wingSide==='LF'?'Linksfuß':'Beidfüßig')).sort((a,b)=>{const dir=wingOrder==='asc'?1:-1;const av=wingSort==='year'?Number(a.year)||0:wingSort==='position'?(a.positions||[]).join(', '):(a.name||'').toLocaleLowerCase('de');const bv=wingSort==='year'?Number(b.year)||0:wingSort==='position'?(b.positions||[]).join(', '):(b.name||'').toLocaleLowerCase('de');return (av>bv?1:av<bv?-1:0)*dir}),[players,wingSide,wingSort,wingOrder]);
